// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

    function setUp() public { c = new C(); }

    function testFuzz_property(address[] memory tos, uint256[] memory amounts) public {
        vm.assume(tos.length > 0);
        vm.assume(tos.length == amounts.length);
        vm.prank(owner);
        bool ok = c.transfer(tos, amounts);
        assertTrue(ok, "successful transfer must return true");
    }
}
